SELECT 'acquisition' AS SECTION, OBJECT_CONSTRUCT_KEEP_NULL('dataset',r.DATASET_NAME,'run_id',r.RUN_ID,'declared_rows',r.ROW_COUNT,'actual_rows',COUNT(d.ROW_INDEX),'unique_indices',COUNT(DISTINCT d.ROW_INDEX),'unique_hashes',COUNT(DISTINCT d.ROW_SHA256),'keys',MIN(TO_JSON(OBJECT_KEYS(TRY_PARSE_JSON(d.PAYLOAD_JSON)))),'verified_at',r.VERIFIED_AT) AS DETAIL FROM VECTOR_RESEARCH.RAW.RESEARCH_ACQUISITION_RUNS r LEFT JOIN VECTOR_RESEARCH.RAW.RESEARCH_ACQUISITION_ROWS d ON r.RUN_ID=d.RUN_ID GROUP BY r.DATASET_NAME,r.RUN_ID,r.ROW_COUNT,r.VERIFIED_AT
UNION ALL SELECT 'sec_packages',OBJECT_CONSTRUCT_KEEP_NULL('ticker',TICKER,'packages',COUNT(*),'unique_accessions',COUNT(DISTINCT ACCESSION),'first_filed',MIN(FILED_DATE),'last_filed',MAX(FILED_DATE),'missing_available',COUNT_IF(AVAILABLE_AT IS NULL),'declared_documents',SUM(DOCUMENT_COUNT)) FROM VECTOR_RESEARCH.RAW.SEC_FILING_PACKAGE_MANIFESTS GROUP BY TICKER
UNION ALL SELECT 'sec_documents',OBJECT_CONSTRUCT_KEEP_NULL('ticker',TICKER,'documents',COUNT(*),'accessions',COUNT(DISTINCT ACCESSION),'unique_document_keys',COUNT(DISTINCT ACCESSION||'/'||DOCUMENT_NAME),'missing_hash',COUNT_IF(DOCUMENT_SHA256 IS NULL),'missing_available',COUNT_IF(AVAILABLE_AT IS NULL)) FROM VECTOR_RESEARCH.RAW.SEC_FILING_DOCUMENTS GROUP BY TICKER
UNION ALL SELECT 'eia_manifest',OBJECT_CONSTRUCT_KEEP_NULL('files',COUNT(*),'distinct_months',COUNT(DISTINCT VINTAGE_MONTH),'first_month',MIN(VINTAGE_MONTH),'last_month',MAX(VINTAGE_MONTH),'missing_availability',COUNT_IF(AVAILABLE_AT IS NULL),'declared_rows',SUM(PLANNED_ROWS+OPERATING_ROWS+CANCELED_ROWS)) FROM VECTOR_RESEARCH.RAW.EIA860M_FILE_MANIFESTS
UNION ALL SELECT 'aws',OBJECT_CONSTRUCT_KEEP_NULL('rows',COUNT(*),'first_time',MIN(PRICE_TIME),'last_time',MAX(PRICE_TIME),'instance_types',COUNT(DISTINCT INSTANCE_TYPE),'zones',COUNT(DISTINCT ZONE_ID),'invalid_price',COUNT_IF(USD_PER_INSTANCE_HOUR IS NULL OR USD_PER_INSTANCE_HOUR<=0),'distinct_quote_keys',COUNT(DISTINCT TO_JSON(ARRAY_CONSTRUCT(PRICE_TIME,ZONE_ID,INSTANCE_TYPE,OPERATING_SYSTEM)))) FROM VECTOR_RESEARCH.RAW.AWS_GPU_SPOT_PRICES
UNION ALL SELECT 'aws_gap',OBJECT_CONSTRUCT_KEEP_NULL('start',START_TIME,'end_exclusive',END_TIME_EXCLUSIVE,'reason',REASON) FROM VECTOR_RESEARCH.RAW.AWS_GPU_SPOT_SOURCE_GAPS
